// src/skills/skill-executor.ts
async function executeVaultSkillTool(plugin, toolId, query, attachmentsContext, signal) {
  const vid = parseVaultSkillPlannerTool(toolId);
  if (!vid) {
    return `Invalid skill tool id: ${toolId}`;
  }
  const manifest = await plugin.skillRegistry.getVaultSkillById(vid);
  if (!manifest) {
    return `Unknown skill \`${vid}\`. Check ${plugin.settings.skillsFolder} and Skills settings.`;
  }
  const system = `${manifest.body}

---
You are invoked as a tool. Respond with clear, factual output for the orchestrator. Be concise.`;
  const user = `=== USER REQUEST ===
${query}

=== ATTACHMENT / URL CONTEXT (may be empty) ===
${attachmentsContext || "(none)"}`;
  const text = await plugin.graphApiService.callRemoteModel(
    [
      { role: "system", content: system },
      { role: "user", content: user }
    ],
    false,
    void 0,
    signal
  );
  return text;
}
async function executeEnricherTool(plugin, toolId, query, attachmentsContext, signal) {
  const id = parseEnrichToolId(toolId);
  if (!id)
    return `Invalid enricher tool id: ${toolId}`;
  const spec = await plugin.enricherRegistry.getById(id);
  if (!spec) {
    const runnable = await plugin.enricherRegistry.listRunnable();
    const ids = runnable.map((e) => e.id).join(", ");
    const folder = plugin.settings.enrichersFolder?.trim() || "OSINTCopilot/custom/enrichers";
    const hint = ids ? `

**Available enricher ids** (use \`enricher_id\` exactly as in JSON \u2014 lowercase, hyphens): ${ids}` : `

No **active** enricher specs found under \`${folder}\`. Add or enable a JSON file; \`id\` must match \`enricher_id\`.`;
    return `Unknown enricher \`${id}\`.${hint}`;
  }
  return executeEnricherHttp(
    spec,
    query,
    attachmentsContext,
    signal,
    plugin.app.vault,
    plugin.settings.credentialsFolder
  );
}

